export function markFor(company: string): EmployerMark | null {
  return EMPLOYER_MARKS[company] ?? null;
}

/**
 * Two letters for an employer with no mark: initials for a multi-word name
 * ("Scale AI" -> SA), the first two letters otherwise ("Dcard" -> Dc). Takes
 * any string, not just a known employer, because Job.company is ingested
 * text -- a board added before this file is regenerated still renders.
 */
export function monogram(company: string): string {
  const words = company.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return "?";
  if (words.length > 1) {
    return (words[0][0] + words[1][0]).toUpperCase();
  }
  const word = words[0];
  return word.length > 1 ? word[0].toUpperCase() + word[1].toLowerCase() : word.toUpperCase();
}
